-- ============================================================
-- Juzgo — Plans page migration + dummy seed
-- Run in Supabase SQL Editor (single run, idempotent-ish: see notes)
-- Aligns countries/esim_plans schema with src/pages/Plans.js,
-- then seeds 42 destinations + 3 regional/global bundles.
-- Package IDs match MOCK_PACKAGES in the claude-proxy worker 1:1.
-- ============================================================

-- ---------- 1. Schema migration (frontend expects these names) ----------
ALTER TABLE countries  RENAME COLUMN flag TO flag_emoji;
ALTER TABLE esim_plans RENAME COLUMN name TO plan_name;
ALTER TABLE esim_plans RENAME COLUMN duration_days TO validity_days;
ALTER TABLE esim_plans RENAME COLUMN price_usd TO price_sgd;  -- prices below are SGD
ALTER TABLE esim_plans ADD COLUMN IF NOT EXISTS is_active boolean NOT NULL DEFAULT true;
ALTER TABLE esim_plans ADD COLUMN IF NOT EXISTS package_id text UNIQUE;  -- links to worker/Airalo package id

-- ---------- 2. Public read access ----------
-- Plans.js reads both tables with the anon key. If RLS is enabled without
-- a SELECT policy, results are silently empty. These are safe public-catalogue reads.
ALTER TABLE countries  ENABLE ROW LEVEL SECURITY;
ALTER TABLE esim_plans ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Public read countries"  ON countries;
DROP POLICY IF EXISTS "Public read esim_plans" ON esim_plans;
CREATE POLICY "Public read countries"  ON countries  FOR SELECT USING (true);
CREATE POLICY "Public read esim_plans" ON esim_plans FOR SELECT USING (true);

-- ---------- 3. Clean slate (tables are empty today; safe) ----------
DELETE FROM esim_plans;
DELETE FROM countries;

-- ---------- 4. Seed countries ----------

-- NOTE: the three Regional/Global rows (codes ASIA, EURO, GLOBAL) are optional —
-- delete them if you want a countries-only dropdown:
--   DELETE FROM esim_plans WHERE country_id IN (SELECT id FROM countries WHERE code IN ('ASIA','EURO','GLOBAL'));
--   DELETE FROM countries WHERE code IN ('ASIA','EURO','GLOBAL');

-- ---------- 5. Seed plans (linked by country code) ----------

-- ---------- 6. Verify ----------
SELECT c.flag_emoji, c.name, count(p.id) AS plans, min(p.price_sgd) AS from_sgd
FROM countries c LEFT JOIN esim_plans p ON p.country_id = c.id
GROUP BY c.id, c.flag_emoji, c.name ORDER BY c.name;
